cells={(0,1),(0,2),(0,4),(0,5),(1,0),(1,1),(1,2),(1,3),(1,4),(1,5),(2,1),(2,2),(2,4),(3,2),(3,3),(3,4)}
# colors orientation mappings: 1 square; 2 missing top-left; 3 missing bottom-left; 4 missing top-right
from itertools import product
shapes={1:{(0,0),(0,1),(1,0),(1,1)},2:{(0,1),(1,0),(1,1)},3:{(0,0),(0,1),(1,1)},4:{(0,0),(1,0),(1,1)}}
placements=[]
for color,sh in shapes.items():
 for r in range(7):
  for c in range(7):
   p={(r+dr,c+dc) for dr,dc in sh}
   if p<=cells: placements.append((color,p))
sol=[]
def search(rem,chosen):
 if not rem:
  sol.append(chosen);return
 x=min(rem)
 for color,p in placements:
  if x in p and p<=rem: search(rem-p,chosen+[(color,p)])
search(cells,[])
len(sol)
